import sys
from functools import lru_cache

def count_permutations(n, k, p):
    MOD = p

    @lru_cache(None)
    def dp(i, last, increasing):
        if i == n:
            return 1
        count = 0
        for next_val in range(1, n + 1):
            if increasing:
                if next_val > last and next_val - last <= k:
                    count = (count + dp(i + 1, next_val, True)) % MOD
                elif next_val < last:
                    count = (count + dp(i + 1, next_val, False)) % MOD
            else:
                if next_val < last and last - next_val <= k:
                    count = (count + dp(i + 1, next_val, False)) % MOD
                elif next_val > last:
                    count = (count + dp(i + 1, next_val, True)) % MOD
        return count

    total_count = 0
    for start in range(1, n + 1):
        total_count = (total_count + dp(1, start, True)) % MOD
        total_count = (total_count + dp(1, start, False)) % MOD

    return total_count

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    k = int(data[1])
    p = int(data[2])
